tool_input.command:
S=$(agent-browser session id --scope worktree --prefix task); agent-browser --session $S open https://books.toscrape.com/catalogue/category/books/mystery_3/index.html >/dev/null; cat <<'EOF' | agent-browser --session $S eval --stdin
(async()=>{let out=[];let url=location.href;while(url){const d=new DOMParser().parseFromString(await (await fetch(url)).text(),'text/html');d.querySelectorAll('article.product_pod').forEach(a=>out.push([a.querySelector('p.star-rating').className,a.querySelector('h3 a').title,a.querySelector('.price_color').textContent]));const n=d.querySelector('li.next a');url=n?new URL(n.getAttribute('href'),url).href:null}
return out.filter(x=>x[0].includes('Five')).sort((a,b)=>parseFloat(a[2].slice(1))-parseFloat(b[2].slice(1))).slice(0,4).concat([out.length])})()
EOF

cat > /tmp/scan.js <<'EOF'
(async () => {
  const out = [];
  let url = location.href;
  while (url) {
    const d = new DOMParser().parseFromString(await (await fetch(url)).text(), 'text/html');
    d.querySelectorAll('article.product_pod').forEach(a => out.push([a.querySelector('p.star-rating').className, a.querySelector('h3 a').title, a.querySelector('.price_color').textContent]));
    const n = d.querySelector('li.next a');
    url = n ? new URL(n.getAttribute('href'), url).href : null;
  }
  const five = out.filter(x => x[0].includes('Five')).sort((a, b) => parseFloat(a[2].slice(1)) - parseFloat(b[2].slice(1)));
  return { total: out.length, five: five.slice(0, 4) };
})()
EOF
agent-browser --session task-b58a53bf90a3 eval --stdin < /tmp/scan.js

